sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var r = new sn_ws.RESTMessageV2('OnPage Secured', 'sendMessage');
        r.setStringParameterNoEscape('URLsub', gs.getProperty('x_onpr_onpage.URLsubdomain'));
        r.setStringParameterNoEscape('token', gs.getProperty('x_onpr_onpage.auth.token'));
        r.setStringParameterNoEscape('key', gs.getProperty('x_onpr_onpage.auth.key'));
        r.setStringParameterNoEscape('ansArray', inputs.reply);
        r.setStringParameterNoEscape('priority', inputs.priority);
        r.setStringParameterNoEscape('subject', encodeURI(inputs.subject));
        r.setStringParameterNoEscape('recipArray', inputs.recipients);
        r.setStringParameterNoEscape('id', inputs.notif);
        r.setStringParameterNoEscape('body', encodeURI(inputs.body));
        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        if (httpStatus != 200) {
            outputs.result = "error;" + httpStatus;
        } else {
            var json = JSON.parse(responseBody);
            if (json[0].accepted == true) {
                outputs.result = "sent;" + json[0].id;
            } else {
                outputs.result = "error;" + json[0].errorDescription;
            }
        }
    } catch (ex) {
        outputs.result = "error;" + ex.message;
    }
})(inputs, outputs);

